  public function executeUpdateApiFirma()
  {
    $this->verificaPrilegio("USUARIO_INFO_API_FIRMA");
    //*******************************************************************************
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id','', 'subscriber');
    $usuario = UsuarioPeer::retrieveByPk($usuariologuiado);    
    //*******************************************************************************
	  $password = trim($this->getRequestParameter('password'));
  	$crtfirmapass = trim($this->getRequestParameter('crtfirmapass'));
    $crtfirmauser = trim($this->getRequestParameter('crtfirmauser'));
	  //*******************************************************************************
	  $sha1pass = sha1($usuario->getSalt(). $password);	
	  if($sha1pass  == $usuario->getPassword() && $usuario->getEstadousuarioId() != 2){
      try{
          $usuario->setLoginFirma($crtfirmauser);
          $usuario->setPassFirma(base64_encode($crtfirmapass));
          $usuario->setUseFirmaElectronica(1);
          $usuario->save();
          //*************************************************************************
          UsuarioPeer::addHistoricoUser($usuario);
          //*************************************************************************
          $baseMail = new BaseMailSimad();
        $baseMail->SetSubject('SGDEA .::. Actualización Usuario');
        $baseMail->SetMsgHTML("Cordial saludo.<br>SGDEA le informa que la información de su certificado de firma digital se registró correctamente en su cuenta de usuario.<br>Un saludo.<br><br>");
          $baseMail->SetAddAddress($usuario->getEmail(), $usuario->getEmail());
          if($baseMail->InitSend() === true){
              $baseMail->writetolog("Alerta enviada: " . $usuario->getUsuarioId() . " Enviado a: " . $usuario->getEmail());
          }else{
              $baseMail->writetolog("Error al enviar alerta: " . $usuario->getUsuarioId() . " Cuenta correo: " . $usuario->getEmail());
          }
      }catch(Exception $ex){
            $baseMail->writetolog("Error del proceso " . $ex->getMessage());
      }
      //*****************************************************************************
      return $this->redirect($this->getRequest()->getScriptName().'/usuario/configSingStamp?qvars='.md5("qvars1"));
	  }else{
      $this->getRequest()->setError("Error", "No se puede actualizar la informaci&oacute;n del usuario, la contraseña esta errada, por favor intente de nuevo");
      $this->forward('usuario', 'configSingStamp');
	  }
	  //*******************************************************************************
	  $this->forward404Unless($this->usuario);    
  }

  public function executeExcel()
  {
    $this->setLayout(false);
    $cr = new Criteria();
    $cr = $this->getCreateCiteria($cr);
    //********************************************************************************
    $cr->clearSelectColumns();
    //********************************************************************************
    $cr->addJoin(UsuarioPeer::DEPENDENCIA_ID,DependenciaPeer::DEPENDENCIA_ID,Criteria::INNER_JOIN);
    $cr->addJoin(UsuarioPeer::REGIONAL_ID,RegionalPeer::REGIONAL_ID,Criteria::INNER_JOIN);
    $cr->addJoin(UsuarioPeer::ESTADOUSUARIO_ID,EstadoUsuarioPeer::ESTADOUSUARIO_ID,Criteria::INNER_JOIN);
    $cr->addJoin(RegionalPeer::ENTIDAD_ID,EntidadPeer::ENTIDAD_ID,Criteria::INNER_JOIN);
    $cr->addJoin(UsuarioPeer::TIPOUSUARIO_ID,TipoUsuarioPeer::TIPOUSUARIO_ID,Criteria::LEFT_JOIN);
    $cr->addJoin(UsuarioPeer::TIPOAUTENTICACION_ID,TipoAutenticacionPeer::TIPOAUTENTICACION_ID,Criteria::LEFT_JOIN);
    //********************************************************************************
    $cr->addAsColumn("USCEDULA",UsuarioPeer::CEDULA);
    $cr->addAsColumn("USNOMBRE",UsuarioPeer::NOMBRE);
    $cr->addAsColumn("USAPELLIDO",UsuarioPeer::APELLIDO);
    $cr->addAsColumn("USUSERNAME",UsuarioPeer::USER_NAME);
    $cr->addAsColumn("DECODIGO",DependenciaPeer::CODIGO);
    $cr->addAsColumn("DENOMBRE",DependenciaPeer::NOMBRE);
    $cr->addAsColumn("DEVERSION",DependenciaPeer::VERSION_INST);
    $cr->addAsColumn("REGDESCRIPCION",RegionalPeer::DESCRIPCION);
    $cr->addAsColumn("ENTDESCRIPCION",EntidadPeer::DESCRIPCION);
    $cr->addAsColumn("ESTUDESCRIPCION",EstadoUsuarioPeer::DESCRIPCION);
    $cr->addAsColumn("USEMAIL",UsuarioPeer::EMAIL);
    $cr->addAsColumn("USFECHACREACION",UsuarioPeer::FECHA_CREACION);
    $cr->addAsColumn("TIPOUSDESCRIPCION",TipoUsuarioPeer::DESCRIPCION);
    $cr->addAsColumn("TIPOUSAUTHDESCRIPCION",TipoAutenticacionPeer::DESCRIPCION);
    $cr->addAsColumn("USLDAP",UsuarioPeer::USUARIO_AD);
    //********************************************************************************
    $cquery1 = "(SELECT STRING_AGG(".CargoPeer::DESCRIPCION.", ', ')
    FROM ".CargoPeer::TABLE_NAME."
    JOIN ".CargoUsuarioPeer::TABLE_NAME." ON ".CargoUsuarioPeer::CARGO_ID."=".CargoPeer::CARGO_ID."
    WHERE ".CargoUsuarioPeer::USUARIO_ID." = ".UsuarioPeer::USUARIO_ID."
    AND ".CargoUsuarioPeer::ES_ACTUAL." = 1 AND ".CargoUsuarioPeer::ES_PRINCIPAL." = 1)";
    $cr->addAsColumn('USCARGOS', $cquery1); 
    //********************************************************************************
    $cquery2 = "(SELECT STRING_AGG(".TipoProcesoComPeer::DESCRIPCION.", ', ')
    FROM ".UsuarioProcesocomPeer::TABLE_NAME."
    JOIN ".TipoProcesoComPeer::TABLE_NAME." ON ".UsuarioProcesocomPeer::TIPOPROCESOCOM_ID."=".TipoProcesoComPeer::TIPOPROCESOCOM_ID."
    WHERE ".UsuarioProcesocomPeer::USUARIO_ID." = ".UsuarioPeer::USUARIO_ID.")";
    $cr->addAsColumn('UROLESCOM', $cquery2);    
    //********************************************************************************
    $cquery3 = "(SELECT STRING_AGG(".RolPeer::DESCRIPCION.", ', ')
    FROM ".RolPorUsuarioPeer::TABLE_NAME."
    JOIN ".RolPeer::TABLE_NAME." ON ".RolPorUsuarioPeer::ROL_ID."=".RolPeer::ROL_ID."
    WHERE ".RolPorUsuarioPeer::USUARIO_ID." = ".UsuarioPeer::USUARIO_ID.")";
    $cr->addAsColumn('UPERFILES', $cquery3);
    //********************************************************************************
    $cr->addAscendingOrderByColumn(UsuarioPeer::USUARIO_ID);
    //********************************************************************************
    $this->usuarios_list = UsuarioPeer::doSelectStmt($cr);
  }
  
