  public function executeHistorial()
  { 
  	
  	$c=new Criteria();
  	$this->parametros="&a=1";
  	$this->parametros.="&usuario_id=".$this->getRequestParameter('usuario_id');
	
	$usuariologuiado=$this->getUser()->getAttribute('usuario_id','', 'subscriber');
  	
  	$c->add(UsUsHistoricoPeer::USUARIO_ID,$this->getRequestParameter('usuario_id'));	
  	$c->add(UsUsHistoricoPeer::ROLUSHISTORICO_ID,2);
	$c->addDescendingOrderByColumn(UsUsHistoricoPeer::USUSHISTORICO_ID);
    
  	$pager=new sfPropelPager('UsUsHistorico',10);
	$pager->setCriteria($c);
	$pager->setPage($this->getRequestParameter('page',1));
	$pager->init();
	
	$this->pager=$pager;   
	$this->controlPaginacion = 1;
	
	$i=0; 
	$this->modificadoPor=array();
	foreach ($pager->getResults() as $usUsHistorico){
	   $this->modificadoPor[$i]=$this->getModificadoPor($usUsHistorico->getHistusuarioId());
	   $i++; 
	}	
    
  }

 public function getModificadoPor($histusuarioId)
