        $usuario->setFirmaDigital($usuario->getFirmaDigital() ? 0 : 1);
        $usuario->save();
        $this->getUser()->setAttribute('firma_digital',$usuario->getFirmaDigital(),  'subscriber');
        $this->tipoconfig = 'firma_digital';
      }elseif($this->getRequestParameter('firmadesatendida')){
        $usuario->setFirmaDesatendida($usuario->getFirmaDesatendida() ? 0 : 1);
        $usuario->save();
        $this->getUser()->setAttribute('firma_desatendida',$usuario->getFirmaDesatendida(), 'subscriber');
        $this->tipoconfig = 'firma_desatendida';
      }
      //***************************************************************************************
      $this->usuario = $usuario;
		}else{
			return sfView::NONE;
		}
	}

