  public function executeUpdate()
  {
    if (!$this->getRequestParameter('usuario_id'))
    {
      $usuario = new Usuario();
      $usuario->setFechaCreacion(date("Y-m-d G:i:s"));
      $insertarHistorico = 0;
      $usuario_anterior = $usuario;
    }else{
      $usuario = UsuarioPeer::retrieveByPk($this->getRequestParameter('usuario_id'));
      $this->forward404Unless($usuario);
      $insertarHistorico = 1;
      $usuario_anterior = clone $usuario;
    }
    //***********************************************************************************************
    $nuevoEstadoUsuarioId = $this->getRequestParameter('estadousuario_id') ? $this->getRequestParameter('estadousuario_id') : null;
    $estadosBloqueoAccion = array(UsuarioPendientesChecker::ESTADO_USUARIO_DESHABILITADO, UsuarioPendientesChecker::ESTADO_USUARIO_SUSPENDIDO);
    if(
      in_array($nuevoEstadoUsuarioId, $estadosBloqueoAccion)
      && !in_array($usuario_anterior->getEstadousuarioId(), $estadosBloqueoAccion)
      && UsuarioPendientesChecker::tienePendientes($usuario->getUsuarioId())
    ){
      $this->getUser()->setFlash('messages_error', UsuarioPendientesChecker::getMensajeBloqueo());
      return $this->redirect($this->getRequest()->getScriptName().'/usuario/edit?usuario_id='.$usuario->getUsuarioId());
    }
    //***********************************************************************************************
    if($insertarHistorico){
      //guarda en historico
      $hist = new HistUsuario();
      $hist->fromArray($usuario->toArray());
      $hist->setFechaModificacion(date('Y-m-d G:i:s'));
      $hist->save();
      //*********************************************************************************************
      $hist_id = $hist->getHistusuarioId();
      $usuario_id = $this->getUser()->getAttribute('usuario_id','', 'subscriber');
      $rolhist = new UsUsHistorico();
      $rolhist->setUsuarioId($usuario_id);
      $rolhist->setRolushistoricoid(1);
      $rolhist->setHistusuarioId($hist_id);
      $rolhist->save();
      //*********************************************************************************************
      $rolhist = new UsUsHistorico();
      $rolhist->setUsuarioId($usuario->getPrimaryKey());
      $rolhist->setRolushistoricoid(2);
      $rolhist->setHistusuarioId($hist_id);
      $rolhist->save();
    }
	  //***********************************************************************************************
    if($this->getRequestParameter('usuario_id') == ""){
        if($this->validarUnico($this->getRequestParameter('user_name'))){
          $errorDuplicado = "Ya existe un usuario con este USER_NAME";
          $this->getRequest()->setError("ERROR ",$errorDuplicado);	
          $this->forward('usuario', 'create');//si no existe se devuelve
        }
    }
    //***********************************************************************************************
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id','', 'subscriber');
    //***********************************************************************************************
    $usuario->setEstadousuarioId($this->getRequestParameter('estadousuario_id') ? $this->getRequestParameter('estadousuario_id') : null);
    $usuario->setDependenciaId($this->getRequestParameter('dependencia_id') ? $this->getRequestParameter('dependencia_id') : null);
    $usuario->setRegionalId($this->getRequestParameter('regional_id') ? $this->getRequestParameter('regional_id') : null);
    $usuario->setTipousuarioId($this->getRequestParameter('tipousuario_id') ? $this->getRequestParameter('tipousuario_id') : null);
    $usuario->setTipoautenticacionId($this->getRequestParameter('tipoautenticacion_id') ? $this->getRequestParameter('tipoautenticacion_id') : null);
    $usuario->setProveedorfirmadigitalId($this->getRequestParameter('proveedorfirmadigital_id') ? $this->getRequestParameter('proveedorfirmadigital_id') : null);
    $usuario->setUserName(trim($this->getRequestParameter('user_name')));
    $usuario->setNombre(trim($this->getRequestParameter('nombre')));
    $usuario->setUseFirmaElectronica($this->getRequestParameter('use_firma_electronica') ? $this->getRequestParameter('use_firma_electronica') : 0);
    $usuario->setCedula(trim($this->getRequestParameter('cedula')));
    $usuario->setEmail(trim($this->getRequestParameter('email')));
    $usuario->setIniciales(trim($this->getRequestParameter('iniciales')));
    $usuario->setExtension(trim($this->getRequestParameter('extension')));
    $usuario->setIntentos(trim($this->getRequestParameter('intentos')));
    $usuario->setPrefijo(trim($this->getRequestParameter('prefijo')));
    $usuario->setCargoId($this->getRequestParameter('cargo_id'));
    $usuario->setApellido(trim($this->getRequestParameter('apellido')));
    $usuario->setFirmaDigital($this->getRequestParameter('firma_digital') ? $this->getRequestParameter('firma_digital') : 0);
    $usuario->setFirmaDesatendida($this->getRequestParameter('firma_desatendida') ? $this->getRequestParameter('firma_desatendida') : 0);
    $usuario->setActivarAlertas($this->getRequestParameter('activar_alertas') ? $this->getRequestParameter('activar_alertas') : 0);
    $usuario->setReceptorDep($this->getRequestParameter('receptor_dep') ? $this->getRequestParameter('receptor_dep') : 0);
    $usuario->setUsuarioAd(trim($this->getRequestParameter('usuario_ad')) ? trim($this->getRequestParameter('usuario_ad')) : null);
	  //***********************************************************************************************
    try{
      $fecha_actualizacion = date_format(new DateTime($this->getRequestParameter('fecha_actualizacion')), "Y-m-d");
    } catch (Exception $e) {
      $timestamp = strtotime(date('Y-m-d')); 
      $fecha_actualizacion = date('Y-m-d', $timestamp);
    }
	  //***********************************************************************************************
    $usuario->setFechaActualizacion($fecha_actualizacion);
    //Falta verificacion de unico en simad
    //***********************************************************************************************
    $dirFotos  = ParametroPeer::retrieveByPk(38)->getValortexto();
    $dirAlias  = ParametroPeer::retrieveByPk(12)->getValortexto();
    $dirTemp  = ParametroPeer::retrieveByPk(65)->getValortexto();
    $dirRaiz = ParametroPeer::retrieveByPk(9)->getValortexto();
    //***********************************************************************************************
    //$usuariologuiado = $usuario->getUsuarioId();
    //$ausuario = UsuarioPeer::retrieveByPK($this->getUser()->getAttribute('usuario_id','', 'subscriber'));
    $entidad_text = trim($usuario->getRegional()->getEntidad()->getDirectorioName());
    $regional_text = trim($usuario->getRegional()->getDirectorioName());
    $entidad_text = preg_replace('#/+#','/',$entidad_text.'/'.$regional_text);
    $alias_tmp = $dirAlias.$entidad_text.'/';
    $alias_directorio = preg_replace('#/+#','/',$alias_tmp.'/'.$dirFotos.'/');
    $target = preg_replace('#/+#','/',$dirRaiz.$entidad_text.'/'.$dirFotos);
    $sourcetmp = $dirRaiz.trim($usuario->getRegional()->getEntidad()->getDirectorioName()).DIRECTORY_SEPARATOR.$dirTemp;
    //********************************************************************************/
    if(trim($this->getRequestParameter('ruta_foto'))!=""){
      $path_directorio = simad_util::createPath($target);
      $arr = explode(",",trim($this->getRequestParameter('ruta_foto')));
      $ruta="";
      foreach ($arr as $result){ 
        if(trim($result) != ""){
                $ruta .= $alias_directorio.basename($result);
                if(file_exists($sourcetmp.'/'.basename($result))){
                  copy($sourcetmp.'/'.basename($result), $path_directorio.'/'.basename($result));
                }else{
                  $source = sfConfig::get('sf_web_dir').'/images/logo_users.png';
                  copy($source, $path_directorio.'/'.basename($result));
                }
        }              
      }
      $usuario->setRutaFoto($ruta);
    }else{    
      $path_directorio = preg_replace('#/+#','/',$dirRaiz.$entidad_text.'/'.$dirFotos);
      $source = sfConfig::get('sf_web_dir').'/images/logo_users.png';     
      /********************************************************************************************/      
      if(!file_exists($path_directorio.'/logo_users.png')){
      	$target = simad_util::createPath($path_directorio);
      	copy($source, $target.'/logo_users.png');
      }      
      /********************************************************************************************/
      $usuario->setRutaFoto($alias_directorio.'logo_users.png');
    }
    //***********************************************************************************************
    if(trim($this->getRequestParameter('firma_electronica'))){
        $dir_firma = "firmas_electronicas";
        $target_firma = $dirRaiz.($entidad_text ? $entidad_text .'/' : "").$dir_firma;
        $firma_alias = $dirAlias.($entidad_text ? $entidad_text .'/' : "").$dir_firma;
        $source_firma = $sourcetmp.DIRECTORY_SEPARATOR.$dir_firma;
        $filename = trim($this->getRequestParameter('firma_electronica'));
        if(file_exists($source_firma.DIRECTORY_SEPARATOR.$filename)){
          $directorio_target = simad_util::createPath($target_firma);
          copy($source_firma.DIRECTORY_SEPARATOR.$filename, $directorio_target.DIRECTORY_SEPARATOR.$filename);
          $usuario->setFirmaElectronica($firma_alias.'/'.$filename);
        }
    }else{
        $usuario->setFirmaElectronica(null);
    }
    //***********************************************************************************************
    $usuario->save();
    //***********************************************************************************************
    AuditLogPeer::guardarAuditoriaLite(UsuarioPeer::OM_CLASS,$usuario_anterior,$usuario,ModulesEnable::Seguridad,$usuario->getCedula(),$usuariologuiado);
    //***********************************************************************************************
	$verificacion = 0;$msg = 0;
  	if($usuario->getTipoautenticacionId() === UserAuthType::LdapNativo){
      $verificacion = UsuarioPeer::verificarActiveDirectory(trim($this->getRequestParameter('usuario_ad')));  	
      //*********************************************************************************************
      if(!$verificacion){
        $usuario->setUsuarioAd(null);
        $usuario->setTipoautenticacionId($usuario_anterior->getTipoautenticacionId());
        $this->getUser()->setFlash('messages_error', 'El usuario no fue encontrado en el directorio activo, no se puede activar la autenticación por directorio activo');
        $msg = 1;
      }else{
        $usuario->setUsuarioAd(trim($this->getRequestParameter('usuario_ad')));
        $this->getUser()->setFlash('messages_error', 'El usuario no fue encontrado en el directorio activo, no se puede activar la autenticación por directorio activo');
      }
      //*********************************************************************************************
      $usuario->save();
      //*********************************************************************************************
      AuditLogPeer::guardarAuditoriaLite(UsuarioPeer::OM_CLASS,$usuario_anterior,$usuario,ModulesEnable::Seguridad,$usuario->getCedula(),$usuariologuiado);
    }
    //***********************************************************************************************
    if ($insertarHistorico == 0) {
      //guarda en historico
      $hist = new HistUsuario();
      $hist->fromArray($usuario->toArray());
      $hist->setFechaModificacion(date('Y-m-d G:i:s'));
      $hist->save();
      //*********************************************************************************************
      $hist_id = $hist->getHistusuarioId();
      $usuario_id = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
      $rolhist = new UsUsHistorico();
      $rolhist->setUsuarioId($usuario_id);
      $rolhist->setRolushistoricoid(1);
      $rolhist->setHistusuarioId($hist_id);
      $rolhist->save();
      //*********************************************************************************************
      $rolhist = new UsUsHistorico();
      $rolhist->setUsuarioId($usuario->getPrimaryKey());
      $rolhist->setRolushistoricoid(2);
      $rolhist->setHistusuarioId($hist_id);
      $rolhist->save();
    }
    //***********************************************************************************************
    $userprcom = $this->getRequestParameter('tipoprocesocom_id');
    UsuarioPeer::deleteUserProccessCom($usuario->getUsuarioId());
    foreach ($userprcom as $key => $value) {
      if($value > 0){
        UsuarioPeer::addUserProcessCom($usuario->getUsuarioId(),$value);
      }
    }
    //***********************************************************************************************
    $roles_usuario = $this->getRequestParameter('perfilesusuario_id');
    RolPorUsuarioPeer::addNewRolByUser($roles_usuario,$usuario->getUsuarioId());
    //***********************************************************************************************
    //$usuario->setReceptorDep($this->getRequestParameter('receptor_dep') ? $this->getRequestParameter('receptor_dep') : 0);
    //$usuario->save();
    //UsuarioPeer::updateReceptorDep($usuario->getPrimaryKey(),$usuario->getDependenciaId());
    //***********************************************************************************************
    $newpassword = $this->getRequestParameter('password');
    if($newpassword!=$usuario->getPassword()){
	    $this->setSha1Password($usuario->getUsuarioId(), $newpassword);
    }
	  //***********************************************************************************************
	  $crCargo = new Criteria();
	  $crCargo->add(CargoUsuarioPeer::USUARIO_ID, $usuario->getUsuarioId());
    $crCargo->add(CargoUsuarioPeer::ES_PRINCIPAL, true);
	  $objCargoUsuario = CargoUsuarioPeer::doSelectOne($crCargo);
	  //***********************************************************************************************
	  if($objCargoUsuario){
      $newcargo_id = $this->getRequestParameter('cargo_id');
      if($newcargo_id != $objCargoUsuario->getCargoId()){
        //*******************************************************************************************
        $new_ucargo = $objCargoUsuario->copy();
          //*****************************************************************************************
        $new_ucargo->setCargoId($newcargo_id);
        $new_ucargo->save();
        //*******************************************************************************************
        $objCargoUsuario->setEsPrincipal(false);
        $objCargoUsuario->setEsActual(false);
        $objCargoUsuario->setFechaFin(date("Y-m-d G:i:s"));
        $objCargoUsuario->save();
        //*******************************************************************************************
      }
	  }else{
      $objCargoUsuario = new CargoUsuario();
      $objCargoUsuario->setCargoId($this->getRequestParameter('cargo_id'));        
      $objCargoUsuario->setUsuarioId($usuario->getUsuarioId());
      $objCargoUsuario->setFechaCreacion(date("Y-m-d G:i:s"));
      $objCargoUsuario->setFechaInicio(date("Y-m-d G:i:s"));
      $objCargoUsuario->setEsPrincipal(true);
      $objCargoUsuario->setEsActual(true);      
      $objCargoUsuario->save();
	}
    //*******************************ENVIAR PASSWORD AL CORREO *********************************************//
	if (!$this->getRequestParameter('usuario_id')){
		$formato_mensaje = "Este mensaje es para informarle que su usuario en SIMAD ha sido creado: "."\n\n\n";
		$formato_mensaje .= "El nombre usuario es: %s"."\n\n\n";
		$formato_mensaje .= "La contrase&ntilde;a es: %s";
		$texto_mensaje = sprintf($formato_mensaje,$this->getRequestParameter('user_name'), $this->getRequestParameter('password') );
		$this->envioEmail($this->getRequestParameter('email'),"Su nueva cuenta en SIMAD WEB",$texto_mensaje);
	}
    //******************************************************************************************************//
    return $this->redirect($this->getRequest()->getScriptName().'/usuario/show?usuario_id='.$usuario->getUsuarioId().'&msg='.$msg);
  }
  
  public function envioEmail($email,$subject,$message)
  {             
    //******************************************************************************************************//
    $cuerpo = '
    <html>
    <head>
    <title></title>
    </head>
    <body>
    <div id="cotenedor">
    <br>'.$message;
    //******************************************************************************************************
    $cuerpo .= '<br></div></body></html>';
    $cabeceras = "Content-type: text/html; charset=UTF-8\r\n";
    //******************************************************************************************************
    $baseMail = new BaseMailSimad();
    $baseMail->SetSubject('Nuevo Usuario SIMAD :: '.$subject);
    $baseMail->SetMsgHTML($cuerpo);
    $baseMail->SetAddAddress($email,$email);        
    if ($baseMail->InitSend() === true) {
       $baseMail->writetolog("Alerta enviada: Nuevo Usuario ==> Enviado a: " . $email);
    }else{
       $baseMail->writetolog("Error al enviar alerta: Cuenta correo ===> " . $email);
    }
  }
  
  public function executeCargarCombos()
  {
  	$usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
  	$objusuario = UsuarioPeer::retrieveByPK($usuario_conectado);
  	$entidad_id = $objusuario->getRegional()->getEntidadId();
    //**********************************************************************************
  	$this->combo_seleccionado = $this->getRequestParameter('combo_seleccionado');
  	$this->disable_combo = "";
  	if($this->combo_seleccionado == "entidades"){
  		$item_seleccion = $this->getRequestParameter('id_seleccionado');
  		$this->entidad_id = $item_seleccion;
	  	$c = new Criteria();
	  	$c->add(DependenciaPeer::ENTIDAD_ID,$item_seleccion);
	  	$c->add(DependenciaPeer::TIPO_TABLA,"TRD");
	  	$c->addAscendingOrderByColumn(DependenciaPeer::NOMBRE);
	  	$this->dependencias_list = DependenciaPeer::doSelect($c);
  	}elseif($this->combo_seleccionado == "dependencias"){
  		$item_seleccion = $this->getRequestParameter('id_seleccionado');
  		$this->regionales_list = "";
  		if($item_seleccion){
	  		$dependencia = DependenciaPeer::retrieveByPK($item_seleccion);
	  		$entidad_id = $dependencia->getEntidadId();
	  		$c = new Criteria();
	  		$c->add(RegionalPeer::ENTIDAD_ID,$entidad_id);
	  		$c->addAscendingOrderByColumn(RegionalPeer::DESCRIPCION);
	  		$this->regionales_list = RegionalPeer::doSelect($c);
  		}else{
  			$this->disable_combo = 'disabled="disabled"';
  		}
  	}else{
  		$this->disable_combo = 'disabled="disabled"';
  	}
  }
  
