  public function borrarCargos($com_enviadaId )
  { 
    $conexion = Propel::getConnection();
    $consulta = " delete FROM %s where %s =".$com_enviadaId;
    $sql = sprintf($consulta,CargoUsuarioPeer::TABLE_NAME,CargoUsuarioPeer::CARGO_ID);
    $sentencia = $conexion->prepare($sql);
    $sentencia->execute();
  }
  
  private function getCreateCiteria(Criteria $c)
  {
  	$this->parametros="&a=1";
  	//**********************************************************************************************
  	$usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
  	$regional_conectado = $this->getUser()->getAttribute('regional_id', '', 'subscriber');
  	$entidad_conectado = $this->getUser()->getAttribute('entidad_id', '', 'subscriber');
  	//**********************************************************************************************
  	if($this->getRequestParameter('intentos')){
  		$c->add(UsuarioPeer::INTENTOS,$this->getRequestParameter('intentos'));
  		$this->parametros.="&intentos=".$this->getRequestParameter('intentos');
  	}
  	//**********************************************************************************************
  	if($this->getRequestParameter('estadousuario_id')){
  		$c->add(UsuarioPeer::ESTADOUSUARIO_ID,$this->getRequestParameter('estadousuario_id'));
  		$this->parametros.="&estadousuario_id=".$this->getRequestParameter('estadousuario_id');
  	}
  	//**********************************************************************************************
    if ($this->getRequestParameter('proveedorfirmadigital_id')) {
      $c->add(UsuarioPeer::PROVEEDORFIRMADIGITAL_ID, $this->getRequestParameter('proveedorfirmadigital_id'));
      $this->parametros .= "&proveedorfirmadigital_id=" . $this->getRequestParameter('proveedorfirmadigital_id');
    }
    //**********************************************************************************************
    if (!empty($this->getRequestParameter('firma_desatendida'))) {
      $c->add(UsuarioPeer::FIRMA_DESATENDIDA, trim($this->getRequestParameter('firma_desatendida')));
      $this->parametros .= "&firma_desatendida=" . trim($this->getRequestParameter('firma_desatendida'));
    }
    //**********************************************************************************************
  	if($this->getRequestParameter('dependencia_id')){
  		$c->add(UsuarioPeer::DEPENDENCIA_ID,$this->getRequestParameter('dependencia_id'));
  		$this->parametros.="&dependencia_id=".$this->getRequestParameter('dependencia_id');
  	}
  	//**********************************************************************************************
  	if($this->getRequestParameter('regional_id')){
  		$c->add(UsuarioPeer::REGIONAL_ID,$this->getRequestParameter('regional_id'));
  		$this->parametros.="&regional_id=".$this->getRequestParameter('regional_id');
  	}
  	//**********************************************************************************************  	
  	if($this->getRequestParameter('nombre')){
  		$c->add(UsuarioPeer::NOMBRE,'%'.$this->getRequestParameter('nombre').'%',Criteria::LIKE);
  		$this->parametros.="&nombre=".$this->getRequestParameter('nombre');
  	}
  	//**********************************************************************************************
  	if($this->getRequestParameter('apellido')){
  		$c->add(UsuarioPeer::APELLIDO,'%'.$this->getRequestParameter('apellido').'%',Criteria::LIKE);
  		$this->parametros.="&apellido=".$this->getRequestParameter('apellido');
  	}
  	//**********************************************************************************************
  	if($this->getRequestParameter('user_name')){
  		$c->add(UsuarioPeer::USER_NAME,'%'.$this->getRequestParameter('user_name').'%',Criteria::LIKE);
  		$this->parametros.="&user_name=".$this->getRequestParameter('user_name');
  	}
  	//**********************************************************************************************
  	if($this->getRequestParameter('cedula')){
  		$c->add(UsuarioPeer::CEDULA,'%'.$this->getRequestParameter('cedula').'%',Criteria::LIKE);
  		$this->parametros.="&cedula=".$this->getRequestParameter('cedula');
  	}
  	//**********************************************************************************************
  	if ($this->getRequestParameter('fechaCreaInicial')) {
  		$c->add(UsuarioPeer::FECHA_CREACION, $this->getRequestParameter('fechaCreaInicial'),Criteria::GREATER_EQUAL);
  		$this->parametros.="&fechaCreaInicial=".$this->getRequestParameter('fechaCreaInicial');
  	}
  	//**********************************************************************************************
  	if ($this->getRequestParameter('fechaCreaFinal')) {
  		$c->addAnd(UsuarioPeer::FECHA_CREACION, $this->getRequestParameter('fechaCreaFinal')." 23:59",Criteria::LESS_EQUAL);
  		$this->parametros.="&fechaCreaFinal=".$this->getRequestParameter('fechaCreaFinal');
  	}
    //**********************************************************************************************
    $use_firma_electronica = $this->getRequestParameter('use_firma_electronica') ? $this->getRequestParameter('use_firma_electronica') : 0;
  	if ( $use_firma_electronica) {
      $c->addAnd(UsuarioPeer::USE_FIRMA_ELECTRONICA,  $use_firma_electronica);
      $this->parametros.="&use_firma_electronica=".$this->getRequestParameter('use_firma_electronica');
  	}
    //***********************************************************************************************
    $userprcom = $this->getRequestParameter('tipoprocesocom_id') ? $this->getRequestParameter('tipoprocesocom_id') : null;
    if(count($userprcom)) {
      $c->addJoin(UsuarioPeer::USUARIO_ID,UsuarioProcesocomPeer::USUARIO_ID);
      if(is_array($userprcom)){
        $c->add(UsuarioProcesocomPeer::TIPOPROCESOCOM_ID,$userprcom,Criteria::IN);
        $this->parametros.="&tipoprocesocom_id=".implode(",",$userprcom);
      }elseif(is_string($userprcom)){
        $c->add(UsuarioProcesocomPeer::TIPOPROCESOCOM_ID,explode(",",$userprcom),Criteria::IN);
        $this->parametros.="&tipoprocesocom_id=".$userprcom;
      }
    }
    //**********************************************************************************************
    $receptor_dep = $this->getRequestParameter('receptor_dep') ? $this->getRequestParameter('receptor_dep') : 0;
  	if ($receptor_dep) {
  		$c->addAnd(UsuarioPeer::RECEPTOR_DEP, $receptor_dep);
  		$this->parametros.="&receptor_dep=".$receptor_dep;
  	}
  	//**********************************************************************************************
  	if($this->getRequestParameter('orden')){
  		$c->addAscendingOrderByColumn(UsuarioPeer::$this->getRequestParameter('orden'));
  		$this->parametros.="&orden=".$this->getRequestParameter('orden');
  	}else{
  		$c->addAscendingOrderByColumn(UsuarioPeer::NOMBRE);
  	}
  	//**********************************************************************************************
  	$listuserxreg = $this->getUser()->checkPerm('LISTAR_USUARIOS_TODAS_REGIONALES', $usuario_conectado);
  	$listuserxent = $this->getUser()->checkPerm('LISTAR_USUARIOS_TODAS_ENTIDADES', $usuario_conectado);
  	//**********************************************************************************************
  	if(!$listuserxreg){
  		$c->add(UsuarioPeer::REGIONAL_ID,$regional_conectado);
  	}elseif(!$listuserxent){
  		$c->addJoin(UsuarioPeer::REGIONAL_ID, RegionalPeer::REGIONAL_ID);
  		$c->add(RegionalPeer::ENTIDAD_ID,$entidad_conectado);
  	}
  	//**********************************************************************************************
  	return $c;
  }
  
  public function executeDigitStatus()
  {
	$this->setLayout(false);
    $isAuthenticated = sfContext::getInstance()->getUser()->isAuthenticated();
    //**********************************************************************************************
    if($isAuthenticated){
      $view_notify = $this->getUser()->getAttribute('badge_view_notify', '', 'subscriber');
      //********************************************************************************************
      $term_list = ComRecibidaPeer::getDigitTaskNotImage($view_notify);
      //********************************************************************************************
      $jsontext = '<span class="badge badge-'.($term_list == 0 ? "success" : "danger").'">'.$term_list.'</span>';
      $data_json = ($jsontext);
    }else{
      $data_json = '<span class="badge badge-danger">(error)</span>';
    }
    //**********************************************************************************************
    $this->getResponse()->setContentType('application/text');      
    return $this->renderText($data_json);
  }

  public function executeUpdateCambioPassword()
  {
    $form_source = $this->getRequestParameter('form_source');
    $this->form_actions = '/backend.php/resumen';
    $url_site = simad_util::endsWith(sfConfig::get('publicUrl'),"/") ? sfConfig::get('publicUrl') : sfConfig::get('publicUrl')."/" ;
    //****************************************************************************
    if(trim($form_source)){
      $this->form_actions = '/backend.php/resumen';
    }
    //****************************************************************************
    $usuariologuiado = $this->getRequestParameter('usuario_id');
    $user = UsuarioPeer::retrieveByPk($usuariologuiado);   
    $sha1pass = sha1($user->getSalt().$this->getRequestParameter('password'));
    //****************************************************************************
    // password is OK ?
    $insertarHistorico = 0;
    if(  $sha1pass  == $user->getPassword()){       
      $insertarHistorico = 1;  
      $this->mensajeError = 0;  
    }else{      	
      $this->mensajeError = 1;
      $this->form_actions = 'backend.php/security/logout?idkey='.$user->getUsuarioId();
    }
    //********************************************************************************
    if($insertarHistorico){
      //guarda en historico
      $hist=new HistUsuario();
      $hist->fromArray($user->toArray());
      $hist->setFechaModificacion( date('Y-m-d G:i:s'));
      $hist->save();
      $hist_id=$hist->getHistusuarioId();        
      //****************************************************************************
      $rolhist = new UsUsHistorico();
      $rolhist->setUsuarioId($user->getUsuarioId());
      $rolhist->setRolushistoricoid(1);
      $rolhist->setHistusuarioId($hist_id);
      $rolhist->save();
      //****************************************************************************
      $rolhist = new UsUsHistorico();
      $rolhist->setUsuarioId($user->getPrimaryKey());
      $rolhist->setRolushistoricoid(2);
      $rolhist->setHistusuarioId($hist_id);
      $rolhist->save();
      //****************************************************************************
      $newpassword = $this->getRequestParameter('passwordNew1');
      $user->setFechaActualizacion(date('Y-m-d'));
      $user->save();
      //****************************************************************************
      if($newpassword != $user->getPassword()){
        $this->setSha1Password($user->getUsuarioId(), $newpassword);
        UsuarioNotificacionPeer::notifyUserTask(array($user->getUsuarioId()),ModuleEnableNotify::Seguridad,null,RolComTypeNotify::CambioPassword);
      }
      //****************************************************************************
      $_SESSION['idCode'] = SED::encryption('RSD501');
      $this->form_actions = '/backend.php/security/logout';
    }
  }

  public function setSha1Password($usuario_id, $password){   
   $user = UsuarioPeer::retrieveByPk($usuario_id);
   if($user){
       $salt= md5(rand(100000,999999).$user->getEmail().$user->getNombre());   	
       $user->setSalt($salt);
       $newpass=sha1($salt.$password);
       $user->setPassword($newpass);
       $user->save();
	     return $newpass;
   }
   return "";      	
}
  
